// ── Teacher Harness — LLM judge comparison (top-2 prompt variants) ───
//
// Second evaluation pass over the SAME fixed baseline as the prompt-efficiency
// run (Llama-3.2-3B / repair_pass / high_very_guided / last_messages_only(8)),
// comparing ONLY the top-2 variants (full_current_prompt vs
// structured_rules_prompt) across the same 12 scripted learner profiles.
//
// REUSES the tutor outputs already generated by the deterministic run (from
// teacher-harness/runs/) — no local model rerun — and layers an LLM judge on
// top. If the required artifacts are missing it reports that instead of
// fabricating; if the judge has no credentials it reports exactly what to set.

import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { resolve } from 'node:path';
import { HARNESS_ROOT, readHarnessEnvValue } from '../config/harness-config';
import { PROMPT_EVAL_PROFILE_TEMPLATES } from './prompt-eval-profiles';
import { buildUnitExcerpt, judgeTurn, resolveJudgeProvider } from './llm-judge';
import { JUDGED_PROMPT_VARIANTS, type JudgedPromptVariant, type JudgedTurn, type JudgeTurnInput } from './llm-judge.types';

const RUNS_DIR = resolve(HARNESS_ROOT, 'runs');
const REPORTS_DIR = resolve(HARNESS_ROOT, 'reports');

/** Default spacing between judge calls (free-tier friendly). Override via env. */
function judgeCallDelayMs(): number {
  const raw = Number(readHarnessEnvValue('TEACHER_HARNESS_JUDGE_CALL_DELAY_MS'));
  return Number.isFinite(raw) && raw >= 0 ? raw : 4_000;
}

function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

function readJson<T>(path: string): T | null {
  try {
    return JSON.parse(readFileSync(path, 'utf8')) as T;
  } catch {
    return null;
  }
}

const PROFILE_BY_ID = new Map(PROMPT_EVAL_PROFILE_TEMPLATES.map((p) => [p.id, p]));

interface ScenarioTurnResult {
  turnId: string;
  learnerMessage: string;
  tutorResponse: string;
  passed: boolean;
  scores?: Record<string, unknown>;
}
interface ScenarioReport {
  turnResults?: ScenarioTurnResult[];
}
interface ScenarioFile {
  turns?: Array<{ id: string; expectedBehaviors?: string[] }>;
}

interface DiscoveredDir {
  variant: JudgedPromptVariant;
  profileId: string;
  timestamp: string;
  dir: string;
}

/** Parse `prompt__<variant>__<caseId>__<timestamp>` run-dir names for the top-2 variants. */
function discoverDirs(): DiscoveredDir[] {
  if (!existsSync(RUNS_DIR)) return [];
  const out: DiscoveredDir[] = [];
  for (const name of readdirSync(RUNS_DIR)) {
    const parts = name.split('__');
    if (parts.length !== 4 || parts[0] !== 'prompt') continue;
    const variant = parts[1] as JudgedPromptVariant;
    if (!JUDGED_PROMPT_VARIANTS.includes(variant)) continue;
    const caseId = parts[2];
    const prefix = `${variant}-`;
    if (!caseId.startsWith(prefix)) continue;
    out.push({ variant, profileId: caseId.slice(prefix.length), timestamp: parts[3], dir: resolve(RUNS_DIR, name) });
  }
  return out;
}

/**
 * Pick the newest timestamp for which BOTH variants have all 12 profiles.
 * Falls back to the newest timestamp present (flagged partial) if none complete.
 */
function pickTimestamp(dirs: DiscoveredDir[]): { timestamp: string | null; complete: boolean } {
  const byTs = new Map<string, DiscoveredDir[]>();
  for (const d of dirs) (byTs.get(d.timestamp) ?? byTs.set(d.timestamp, []).get(d.timestamp)!).push(d);
  const timestamps = [...byTs.keys()].sort().reverse();
  const need = PROMPT_EVAL_PROFILE_TEMPLATES.length;
  for (const ts of timestamps) {
    const group = byTs.get(ts)!;
    const complete = JUDGED_PROMPT_VARIANTS.every(
      (v) => new Set(group.filter((g) => g.variant === v).map((g) => g.profileId)).size >= need,
    );
    if (complete) return { timestamp: ts, complete: true };
  }
  return { timestamp: timestamps[0] ?? null, complete: false };
}

export interface JudgeEvalArtifacts {
  timestamp: string;
  unitExcerpt: string;
  inputs: JudgeTurnInput[];
}

/** Load the reusable tutor outputs for the top-2 variants into judge inputs. */
export function loadJudgeInputs(): { ok: true; data: JudgeEvalArtifacts } | { ok: false; reason: string } {
  const dirs = discoverDirs();
  if (dirs.length === 0) {
    return { ok: false, reason: `No prompt-eval artifacts under ${RUNS_DIR}. Run \`npm run evaluate:prompts\` first.` };
  }
  const { timestamp, complete } = pickTimestamp(dirs);
  if (!timestamp) return { ok: false, reason: 'Could not determine a usable artifact timestamp.' };
  if (!complete) {
    return {
      ok: false,
      reason:
        `No complete artifact set: the newest run (${timestamp}) does not have all ` +
        `${PROMPT_EVAL_PROFILE_TEMPLATES.length} profiles for BOTH top-2 variants. ` +
        'Re-run `npm run evaluate:prompts` (or the top-2) so a full set exists.',
    };
  }

  const chosen = dirs.filter((d) => d.timestamp === timestamp);
  let unitExcerpt = '';
  const inputs: JudgeTurnInput[] = [];

  for (const d of chosen) {
    const report = readJson<ScenarioReport>(resolve(d.dir, 'scenario-report.json'));
    const scenario = readJson<ScenarioFile>(resolve(d.dir, 'scenario.json'));
    if (!unitExcerpt) {
      const unit = readJson<Parameters<typeof buildUnitExcerpt>[0]>(resolve(d.dir, 'unit.snapshot.json'));
      if (unit) unitExcerpt = buildUnitExcerpt(unit);
    }
    const template = PROFILE_BY_ID.get(d.profileId);
    const expectedByTurn = new Map((scenario?.turns ?? []).map((t) => [t.id, t.expectedBehaviors ?? []]));
    for (const tr of report?.turnResults ?? []) {
      inputs.push({
        promptVariant: d.variant,
        profileId: d.profileId,
        profileTitle: template?.title ?? d.profileId,
        profileDescription: template?.description ?? '',
        category: template?.category ?? 'unknown',
        turnId: tr.turnId,
        learnerMessage: tr.learnerMessage,
        tutorResponse: tr.tutorResponse,
        expectedBehaviors: expectedByTurn.get(tr.turnId) ?? [],
        deterministicPassed: typeof tr.passed === 'boolean' ? tr.passed : null,
        deterministicScores: tr.scores ?? null,
      });
    }
  }

  if (inputs.length === 0) {
    return { ok: false, reason: `Artifacts for ${timestamp} contained no turn results to judge.` };
  }
  return { ok: true, data: { timestamp, unitExcerpt, inputs } };
}

export interface JudgeEvalOutput {
  finishedAt: string;
  judgeAvailable: boolean;
  judgeModel?: string;
  judgeProviderKind?: string;
  judgeSource?: string;
  judgeUnavailableReason?: string;
  neededEnv?: string[];
  reusedArtifacts: boolean;
  artifactTimestamp?: string;
  totalTurns: number;
  judgedOk: number;
  judgeFailed: number;
  repaired: number;
  results: JudgedTurn[];
  incompleteReason?: string;
}

export interface RunJudgeInput {
  timestamp: string;
  verbose?: boolean;
}

/** Run the LLM judge over the reused top-2 tutor outputs. */
export async function runLlmJudgeEvaluation(input: RunJudgeInput): Promise<JudgeEvalOutput> {
  const log = (m: string) => input.verbose && console.log(m);
  const base: JudgeEvalOutput = {
    finishedAt: input.timestamp,
    judgeAvailable: false,
    reusedArtifacts: false,
    totalTurns: 0,
    judgedOk: 0,
    judgeFailed: 0,
    repaired: 0,
    results: [],
  };

  const loaded = loadJudgeInputs();
  if (!loaded.ok) return { ...base, incompleteReason: loaded.reason };
  const { timestamp, unitExcerpt, inputs } = loaded.data;
  log(`\n📂 reusing tutor outputs from run ${timestamp} — ${inputs.length} turns across the top-2 variants (no rerun).`);

  const judge = resolveJudgeProvider();
  if (!judge.available || !judge.provider) {
    return {
      ...base,
      reusedArtifacts: true,
      artifactTimestamp: timestamp,
      totalTurns: inputs.length,
      judgeUnavailableReason: judge.unavailableReason,
      neededEnv: judge.neededEnv,
      incompleteReason: judge.unavailableReason,
    };
  }
  log(`⚖️  LLM judge: ${judge.modelName} [${judge.providerKind}] (source: ${judge.source}). Judging ${inputs.length} turns…`);

  const delay = judgeCallDelayMs();
  const results: JudgedTurn[] = [];
  let ok = 0;
  let failed = 0;
  let repaired = 0;
  for (let i = 0; i < inputs.length; i += 1) {
    if (i > 0 && delay > 0) await sleep(delay);
    const r = await judgeTurn(judge.provider, inputs[i], unitExcerpt);
    results.push(r);
    if (r.ok) {
      ok += 1;
      if (r.repaired) repaired += 1;
      log(
        `   ${r.score.pass ? '✅' : '❌'} ${r.input.promptVariant}/${r.input.profileId}/${r.input.turnId} — overall ${r.score.overallScore}/10${r.repaired ? ' (repaired)' : ''}`,
      );
    } else {
      failed += 1;
      log(`   ⚠️  ${r.input.promptVariant}/${r.input.profileId}/${r.input.turnId} — ${r.error}`);
    }
  }

  return {
    ...base,
    judgeAvailable: true,
    judgeModel: judge.modelName,
    judgeProviderKind: judge.providerKind,
    judgeSource: judge.source,
    reusedArtifacts: true,
    artifactTimestamp: timestamp,
    totalTurns: inputs.length,
    judgedOk: ok,
    judgeFailed: failed,
    repaired,
    results,
    incompleteReason: failed === inputs.length ? 'Every judge call failed — see errors above.' : undefined,
  };
}

/** Read the newest deterministic prompt-efficiency report (for the comparison table). */
export function readLatestDeterministic(): Record<JudgedPromptVariant, Record<string, unknown>> | null {
  if (!existsSync(REPORTS_DIR)) return null;
  const files = readdirSync(REPORTS_DIR)
    .filter((f) => f.startsWith('prompt-efficiency-evaluation-') && f.endsWith('.json'))
    .sort()
    .reverse();
  for (const f of files) {
    const report = readJson<{ ranking?: Array<Record<string, unknown>> }>(resolve(REPORTS_DIR, f));
    const ranking = report?.ranking;
    if (!ranking) continue;
    const out = {} as Record<JudgedPromptVariant, Record<string, unknown>>;
    let found = 0;
    for (const v of JUDGED_PROMPT_VARIANTS) {
      const row = ranking.find((r) => r.promptVariant === v);
      if (row) {
        out[v] = row;
        found += 1;
      }
    }
    if (found === JUDGED_PROMPT_VARIANTS.length) return out;
  }
  return null;
}
